#!/usr/bin/env bash
# Question 9: Unhealthy Deployment ${Q9_APP}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q9_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q9_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q9_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: ${Q9_APP}-config
  namespace: ${Q9_NS}
data:
  mode: production
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q9_APP}
  namespace: ${Q9_NS}
  labels: { app: ${Q9_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q9_APP} }
  template:
    metadata:
      labels: { app: ${Q9_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
            limits: { cpu: 250m, memory: 128Mi }
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          livenessProbe:
            tcpSocket: { port: 80 }
            periodSeconds: 5
            failureThreshold: 2
          env:
            - name: APP_MODE
              valueFrom:
                configMapKeyRef: { name: ${Q9_APP}-config, key: mode }
EOF
kubectl -n "${Q9_NS}" get deployment "${Q9_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q9.uid"
chmod 644 "/var/tmp/cka-q9.uid"

(
case "${Q9_FAULT}" in
  image-pull)
    kubectl -n "${Q9_NS}" set image "deployment/${Q9_APP}" web=nginx:1.27-alpne
    ;;
  bad-command)
    kubectl -n "${Q9_NS}" patch deployment "${Q9_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["nginx","-g","daemon off; worker_procs 2;"]}]}}}}'
    ;;
  no-bash)
    kubectl -n "${Q9_NS}" patch deployment "${Q9_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["/bin/bash","-c","nginx -g daemon off;"]}]}}}}'
    ;;
  configmap-key)
    kubectl -n "${Q9_NS}" patch configmap "${Q9_APP}-config" --type=json -p '[{"op":"move","from":"/data/mode","path":"/data/mod"}]'
    ;;
  exits-cleanly)
    kubectl -n "${Q9_NS}" patch deployment "${Q9_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["sh","-c","nginx -t && echo configuration ok"]}]}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q9_FAULT_2}" in
  requests-too-large)
    max=0
    for n in $(kubectl get nodes -l '!node-role.kubernetes.io/control-plane' -o name); do
      ki=$(kubectl get "$n" -o jsonpath='{.status.allocatable.memory}' | sed 's/Ki$//')
      (( ki > max )) && max=$ki
    done
    (( max > 0 )) || { echo "could not read the workers' allocatable memory" >&2; exit 1; }
    mem="$(( max / 1024 + 128 ))Mi"
    kubectl -n "${Q9_NS}" set resources "deployment/${Q9_APP}" --requests=cpu=50m,memory="$mem" --limits=cpu=250m,memory="$mem"
    ;;
  node-selector)
    kubectl -n "${Q9_NS}" patch deployment "${Q9_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"nodeSelector":{"disktype":"ssd"}}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
kubectl -n "${Q9_NS}" scale "deployment/${Q9_APP}" --replicas=2
notready=0
for _ in $(seq 1 10); do
  states="$(kubectl -n "${Q9_NS}" get pods -l "app=${Q9_APP}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
  if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
  if kubectl -n "${Q9_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
  if grep -qE '^Running False' <<< "$states"; then
    notready=$((notready + 1))
    (( notready >= 3 )) && break
  else
    notready=0
  fi
  sleep 2
done
)
